    if(event.target.closest("[data-new-menu]")){$("#menu-editor").innerHTML=menuForm();return;}
    if(event.target.closest("[data-add-modifier-group]")){const container=$("#modifier-groups");if(container)container.insertAdjacentHTML("beforeend",modifierEditor());return;}
    const removeModifierGroup=event.target.closest("[data-remove-modifier-group]");if(removeModifierGroup){removeModifierGroup.closest(".modifier-group-editor")?.remove();return;}
    const archive=event.target.closest("[data-archive-menu]");if(archive){if(confirm("Archive this menu item? Existing orders will keep their snapshots.")){try{await request(`/menu-items/${archive.dataset.archiveMenu}`,{method:"DELETE"});showToast("Menu item archived.");await openRoute("menu");}catch(e){showAlert(e.message,true)}}return;}
    const editCategory=event.target.closest("[data-edit-category]");if(editCategory){$("#category-editor").innerHTML=categoryForm(state.cache.categories.find(c=>c.id===editCategory.dataset.editCategory));return;}if(event.target.closest("[data-new-category]")){$("#category-editor").innerHTML=categoryForm();return;}
    const order=event.target.closest("[data-order]");if(order){if(!$("#record-drawer"))await openRoute("orders");showOrderDrawer(order.dataset.order).catch(e=>showAlert(e.message,true));return;}
    const catering=event.target.closest("[data-catering-request]");if(catering){showCateringDrawer(catering.dataset.cateringRequest).catch(e=>showAlert(e.message,true));return;}
