    if(event.target.closest("[data-apply-catering-filters]")){const params=new URLSearchParams();const search=$("#catering-search").value.trim();const statusValue=$("#catering-status").value;if(search)params.set("search",search);if(statusValue)params.set("status",statusValue);await renderCatering(`?${params}`);return;}
    const transition=event.target.closest("[data-transition]");if(transition){let reason="";if(transition.dataset.transition==="CANCELLED"){reason=prompt("Cancellation reason:")||"";if(!reason)return;}else if(state.route!=="kitchen"&&!confirm(`Move this order to ${titleCase(transition.dataset.transition)}?`))return;try{await request(`/orders/${encodeURIComponent(transition.dataset.orderNumber)}/transition`,{method:"POST",body:JSON.stringify({status:transition.dataset.transition,reason})});showToast("Order status updated.");if(state.route==="kitchen")await renderKitchen();else await showOrderDrawer(transition.dataset.orderNumber);}catch(e){showAlert(e.message,true)}return;}
    if(event.target.closest("[data-refresh-kitchen]")){renderKitchen().catch(e=>showAlert(e.message,true));return;}
