    const editSpecial=event.target.closest("[data-edit-special]");if(editSpecial){$("#special-editor").innerHTML=specialFormWithImage(state.cache.specials.find(s=>String(s.id)===editSpecial.dataset.editSpecial));return;}if(event.target.closest("[data-new-special]")){$("#special-editor").innerHTML=specialFormWithImage();return;}
    const delGallery=event.target.closest("[data-delete-gallery]");if(delGallery){if(confirm("Delete this gallery photo?")){try{await request(`/gallery/${delGallery.dataset.deleteGallery}`,{method:"DELETE"});showToast("Gallery photo deleted.");await openRoute("gallery");}catch(e){showAlert(e.message,true)}}return;}
    const delException=event.target.closest("[data-delete-exception]");if(delException){if(confirm("Remove this date exception?")){try{await request(`/hours-exceptions/${delException.dataset.deleteException}`,{method:"DELETE"});showToast("Hours exception removed.");await openRoute("hours");}catch(e){showAlert(e.message,true)}}return;}
    const toggleUser=event.target.closest("[data-toggle-user]");if(toggleUser){const active=toggleUser.dataset.userActive==="true";if(confirm(`${active?"Disable":"Enable"} this user?`)){try{await request(`/users/${toggleUser.dataset.toggleUser}`,{method:"PATCH",body:JSON.stringify({isActive:!active})});showToast("User updated.");await openRoute("users");}catch(e){showAlert(e.message,true)}}}
